```go
package worker
import "sync"
func Squares(nums []int, workers int) []int {
 out := make([]int,len(nums))
 if workers<1 { workers=1 }; if workers>len(nums) { workers=len(nums) }
 jobs:=make(chan int); var wg sync.WaitGroup
 for w:=0; w<workers; w++ { wg.Add(1); go func(){ defer wg.Done(); for i:=range jobs {out[i]=nums[i]*nums[i]} }() }
 for i:=range nums { jobs<-i }; close(jobs); wg.Wait(); return out
}
```

