package webapp

import (
	"context"
	"errors"
	"fmt"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	apimeta "k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	"k8s.io/apimachinery/pkg/types"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/client/fake"
	"testing"
)

var ctx = context.Background()
var key = types.NamespacedName{Namespace: "opsforge-lab", Name: "demo"}

func sample() *WebApp {
	return &WebApp{TypeMeta: metav1.TypeMeta{APIVersion: GroupVersion.String(), Kind: "WebApp"}, ObjectMeta: metav1.ObjectMeta{Name: key.Name, Namespace: key.Namespace, UID: types.UID("11111111-2222-3333-4444-555555555555"), Generation: 1}, Spec: WebAppSpec{Image: "nginxinc/nginx-unprivileged:1.27", Replicas: 2, Port: 8080}}
}
func setup(t *testing.T, objects ...client.Object) (*Reconciler, client.Client) {
	t.Helper()
	s := runtime.NewScheme()
	for _, add := range []func(*runtime.Scheme) error{AddToScheme, corev1.AddToScheme, appsv1.AddToScheme} {
		if err := add(s); err != nil {
			t.Fatal(err)
		}
	}
	c := fake.NewClientBuilder().WithScheme(s).WithStatusSubresource(&WebApp{}, &appsv1.Deployment{}).WithObjects(objects...).Build()
	return &Reconciler{Client: c, Reader: c, Scheme: s, Namespace: key.Namespace}, c
}
func reconcile(t *testing.T, r *Reconciler) {
	t.Helper()
	if _, err := r.Reconcile(ctx, ctrl.Request{NamespacedName: key}); err != nil {
		t.Fatal(err)
	}
}
func get(t *testing.T, c client.Client, obj client.Object) {
	t.Helper()
	if err := c.Get(ctx, key, obj); err != nil {
		t.Fatal(err)
	}
}
func versions(t *testing.T, c client.Client) [3]string {
	t.Helper()
	a, d, s := &WebApp{}, &appsv1.Deployment{}, &corev1.Service{}
	get(t, c, a)
	get(t, c, d)
	get(t, c, s)
	return [3]string{a.ResourceVersion, d.ResourceVersion, s.ResourceVersion}
}
func TestCreateAndRepeatedReconcileIsStable(t *testing.T) {
	r, c := setup(t, sample())
	reconcile(t, r)
	reconcile(t, r)
	before := versions(t, c)
	reconcile(t, r)
	if after := versions(t, c); after != before {
		t.Fatalf("stable reconcile wrote resources: %v -> %v", before, after)
	}
	dl, sl := &appsv1.DeploymentList{}, &corev1.ServiceList{}
	if err := c.List(ctx, dl); err != nil {
		t.Fatal(err)
	}
	if err := c.List(ctx, sl); err != nil {
		t.Fatal(err)
	}
	if len(dl.Items) != 1 || len(sl.Items) != 1 {
		t.Fatal("duplicate children")
	}
	if err := owned(&dl.Items[0], sample()); err != nil {
		t.Fatal(err)
	}
	if err := owned(&sl.Items[0], sample()); err != nil {
		t.Fatal(err)
	}
	a := &WebApp{}
	get(t, c, a)
	if !apimeta.IsStatusConditionFalse(a.Status.Conditions, "Ready") {
		t.Fatal("new Deployment falsely Ready")
	}
}
func TestSpecUpdatePreservesServiceAllocatedFields(t *testing.T) {
	r, c := setup(t, sample())
	reconcile(t, r)
	svc := &corev1.Service{}
	get(t, c, svc)
	svc.Spec.ClusterIP = "10.96.0.12"
	svc.Spec.ClusterIPs = []string{"10.96.0.12"}
	svc.Spec.IPFamilies = []corev1.IPFamily{corev1.IPv4Protocol}
	policy := corev1.IPFamilyPolicySingleStack
	svc.Spec.IPFamilyPolicy = &policy
	if err := c.Update(ctx, svc); err != nil {
		t.Fatal(err)
	}
	a := &WebApp{}
	get(t, c, a)
	a.Spec.Image = "nginxinc/nginx-unprivileged:1.28"
	a.Spec.Port = 8081
	a.Spec.Replicas = 3
	a.Generation = 2
	if err := c.Update(ctx, a); err != nil {
		t.Fatal(err)
	}
	reconcile(t, r)
	get(t, c, svc)
	if svc.Spec.ClusterIP != "10.96.0.12" || len(svc.Spec.ClusterIPs) != 1 || len(svc.Spec.IPFamilies) != 1 || svc.Spec.IPFamilyPolicy == nil || *svc.Spec.IPFamilyPolicy != policy || svc.Spec.Ports[0].Port != 8081 {
		t.Fatalf("allocated fields lost: %+v", svc.Spec)
	}
	dep := &appsv1.Deployment{}
	get(t, c, dep)
	if *dep.Spec.Replicas != 3 || dep.Spec.Template.Spec.Containers[0].Image != a.Spec.Image {
		t.Fatal("spec not reconciled")
	}
	// This only tests declaration updates; changing containerPort does not reconfigure a real image listener.
}
func TestReadyRequiresCurrentDeploymentGeneration(t *testing.T) {
	r, c := setup(t, sample())
	reconcile(t, r)
	dep := &appsv1.Deployment{}
	get(t, c, dep)
	dep.Generation = 2
	if err := c.Update(ctx, dep); err != nil {
		t.Fatal(err)
	}
	dep.Status = appsv1.DeploymentStatus{ObservedGeneration: 1, Replicas: 2, UpdatedReplicas: 2, ReadyReplicas: 2, AvailableReplicas: 2}
	if err := c.Status().Update(ctx, dep); err != nil {
		t.Fatal(err)
	}
	reconcile(t, r)
	a := &WebApp{}
	get(t, c, a)
	if !apimeta.IsStatusConditionFalse(a.Status.Conditions, "Ready") {
		t.Fatal("stale generation accepted")
	}
	get(t, c, dep)
	dep.Status.ObservedGeneration = 2
	if err := c.Status().Update(ctx, dep); err != nil {
		t.Fatal(err)
	}
	reconcile(t, r)
	get(t, c, a)
	if !apimeta.IsStatusConditionTrue(a.Status.Conditions, "Ready") || a.Status.ObservedGeneration != 1 || a.Status.ReadyReplicas != 2 {
		t.Fatal("current generation not Ready")
	}
}
func TestForeignServiceIsNotAdopted(t *testing.T) {
	foreign := &corev1.Service{ObjectMeta: metav1.ObjectMeta{Name: key.Name, Namespace: key.Namespace}, Spec: corev1.ServiceSpec{ClusterIP: "10.96.0.99"}}
	r, c := setup(t, sample(), foreign)
	if _, err := r.Reconcile(ctx, ctrl.Request{NamespacedName: key}); err == nil {
		t.Fatal("foreign object adopted")
	}
	svc := &corev1.Service{}
	get(t, c, svc)
	if svc.Spec.ClusterIP != "10.96.0.99" || len(svc.OwnerReferences) != 0 {
		t.Fatal("foreign object mutated")
	}
}

type onceConflict struct {
	client.Client
	remaining int
	attempts  int
}

func (c *onceConflict) Update(ctx context.Context, obj client.Object, opts ...client.UpdateOption) error {
	if _, ok := obj.(*appsv1.Deployment); ok {
		c.attempts++
		if c.remaining > 0 {
			c.remaining--
			return apierrors.NewConflict(schema.GroupResource{Group: "apps", Resource: "deployments"}, obj.GetName(), fmt.Errorf("injected conflict"))
		}
	}
	return c.Client.Update(ctx, obj, opts...)
}
func TestUpdateConflictReReadsAndRetries(t *testing.T) {
	r, c := setup(t, sample())
	reconcile(t, r)
	a := &WebApp{}
	get(t, c, a)
	a.Spec.Replicas = 4
	a.Generation = 2
	if err := c.Update(ctx, a); err != nil {
		t.Fatal(err)
	}
	wrapped := &onceConflict{Client: c, remaining: 1}
	r.Client = wrapped
	reconcile(t, r)
	dep := &appsv1.Deployment{}
	get(t, c, dep)
	if wrapped.attempts != 2 || *dep.Spec.Replicas != 4 {
		t.Fatalf("conflict not retried: %d", wrapped.attempts)
	}
}
func TestOldObservationCannotStampNewSpecReady(t *testing.T) {
	old := sample()
	r, c := setup(t, old)
	current := &WebApp{}
	get(t, c, current)
	current.Generation = 2
	current.Spec.Image = "different"
	if err := c.Update(ctx, current); err != nil {
		t.Fatal(err)
	}
	if err := r.writeStatus(ctx, old, 2, true, "Available", "old observation"); !errors.Is(err, ErrSuperseded) {
		t.Fatalf("unexpected error: %v", err)
	}
	get(t, c, current)
	if current.Status.ObservedGeneration == 2 || apimeta.IsStatusConditionTrue(current.Status.Conditions, "Ready") {
		t.Fatal("new spec falsely acknowledged")
	}
}
func TestDeletionDoesNotCreateChildren(t *testing.T) {
	a := sample()
	now := metav1.Now()
	a.DeletionTimestamp = &now
	a.Finalizers = []string{"lab.opsforge.dev/test-hold"}
	r, c := setup(t, a)
	reconcile(t, r)
	dep := &appsv1.Deployment{}
	if err := c.Get(ctx, key, dep); !apierrors.IsNotFound(err) {
		t.Fatalf("unexpected child: %v", err)
	}
}
func TestMissingObjectAndOtherNamespaceAreIgnored(t *testing.T) {
	r, _ := setup(t)
	reconcile(t, r)
	if _, err := r.Reconcile(ctx, ctrl.Request{NamespacedName: types.NamespacedName{Namespace: "other", Name: "demo"}}); err != nil {
		t.Fatal(err)
	}
}
func TestInvalidSpecIsRejected(t *testing.T) {
	a := sample()
	a.Spec.Port = 0
	r, c := setup(t, a)
	if _, err := r.Reconcile(ctx, ctrl.Request{NamespacedName: key}); err == nil {
		t.Fatal("invalid port accepted")
	}
	dep := &appsv1.Deployment{}
	if err := c.Get(ctx, key, dep); !apierrors.IsNotFound(err) {
		t.Fatal("created child for invalid spec")
	}
}

