package webapp

import (
	"context"
	"errors"
	"fmt"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	apimeta "k8s.io/apimachinery/pkg/api/meta"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/apimachinery/pkg/util/intstr"
	"k8s.io/apimachinery/pkg/util/validation"
	"k8s.io/client-go/util/retry"
	"reflect"
	ctrl "sigs.k8s.io/controller-runtime"
	"sigs.k8s.io/controller-runtime/pkg/client"
	"sigs.k8s.io/controller-runtime/pkg/controller/controllerutil"
)

const labelKey = "lab.opsforge.dev/webapp-uid"

var ErrSuperseded = errors.New("WebApp identity or generation changed")

type Reconciler struct {
	client.Client
	Reader    client.Reader // production: APIReader, not the eventually consistent cache
	Scheme    *runtime.Scheme
	Namespace string
}

func (r *Reconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).For(&WebApp{}).
		Owns(&appsv1.Deployment{}).Owns(&corev1.Service{}).Complete(r)
}
func (r *Reconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
	if req.Namespace != r.Namespace {
		return ctrl.Result{}, nil
	}
	app := &WebApp{}
	if err := r.Reader.Get(ctx, req.NamespacedName, app); err != nil {
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}
	if !app.DeletionTimestamp.IsZero() {
		return ctrl.Result{}, nil
	}
	if len(validation.IsDNS1035Label(app.Name)) != 0 || app.UID == "" || app.Spec.Image == "" || app.Spec.Replicas < 0 || app.Spec.Replicas > 10 || app.Spec.Port < 1 || app.Spec.Port > 65535 {
		return ctrl.Result{}, fmt.Errorf("invalid WebApp UID/image/replicas/port")
	}
	dep, err := r.ensureDeployment(ctx, app)
	if err == nil {
		err = r.ensureService(ctx, app)
	}
	if err != nil {
		statusErr := r.writeStatus(ctx, app, 0, false, "ReconcileError", err.Error())
		if statusErr != nil {
			return ctrl.Result{}, fmt.Errorf("%w; status update: %v", err, statusErr)
		}
		return ctrl.Result{}, err
	}
	n := app.Spec.Replicas
	ready := dep.Status.ObservedGeneration >= dep.Generation &&
		dep.Status.UpdatedReplicas == n && dep.Status.ReadyReplicas == n &&
		dep.Status.AvailableReplicas == n && dep.Status.Replicas == n
	reason, message := "Progressing", "Waiting for the current Deployment generation and all replicas"
	if ready {
		reason, message = "Available", "Current Deployment replicas are ready and available"
	}
	if err := r.writeStatus(ctx, app, dep.Status.ReadyReplicas, ready, reason, message); err != nil {
		if errors.Is(err, ErrSuperseded) {
			return ctrl.Result{Requeue: true}, nil
		}
		return ctrl.Result{}, err
	}
	return ctrl.Result{}, nil
}
func owned(obj client.Object, app *WebApp) error {
	owner := metav1.GetControllerOf(obj)
	if owner == nil || owner.UID != app.UID || owner.Name != app.Name || owner.Kind != "WebApp" || owner.APIVersion != GroupVersion.String() {
		return fmt.Errorf("refusing to adopt %T %s/%s: different or missing controller owner", obj, obj.GetNamespace(), obj.GetName())
	}
	return nil
}
func (r *Reconciler) ensureDeployment(ctx context.Context, app *WebApp) (*appsv1.Deployment, error) {
	var result *appsv1.Deployment
	err := retry.RetryOnConflict(retry.DefaultRetry, func() error {
		dep := &appsv1.Deployment{}
		key := types.NamespacedName{Namespace: app.Namespace, Name: app.Name}
		err := r.Reader.Get(ctx, key, dep)
		if apierrors.IsNotFound(err) {
			labels := map[string]string{labelKey: string(app.UID)}
			dep = &appsv1.Deployment{ObjectMeta: metav1.ObjectMeta{Name: app.Name, Namespace: app.Namespace}, Spec: appsv1.DeploymentSpec{
				Replicas: &app.Spec.Replicas, Selector: &metav1.LabelSelector{MatchLabels: labels},
				Template: corev1.PodTemplateSpec{ObjectMeta: metav1.ObjectMeta{Labels: labels}, Spec: corev1.PodSpec{Containers: []corev1.Container{{Name: "web", Image: app.Spec.Image, Ports: []corev1.ContainerPort{{Name: "http", ContainerPort: app.Spec.Port, Protocol: corev1.ProtocolTCP}}}}}},
			}}
			if err := controllerutil.SetControllerReference(app, dep, r.Scheme); err != nil {
				return err
			}
			if err := r.Create(ctx, dep); err != nil {
				return err
			} // AlreadyExists is retried by the workqueue.
			result = dep
			return nil
		}
		if err != nil {
			return err
		}
		if err := owned(dep, app); err != nil {
			return err
		}
		expected := &metav1.LabelSelector{MatchLabels: map[string]string{labelKey: string(app.UID)}}
		if !reflect.DeepEqual(dep.Spec.Selector, expected) {
			return fmt.Errorf("managed Deployment selector differs; manual migration required")
		}
		old := dep.DeepCopy()
		replicas := app.Spec.Replicas
		dep.Spec.Replicas = &replicas
		if dep.Spec.Template.Labels == nil {
			dep.Spec.Template.Labels = map[string]string{}
		}
		dep.Spec.Template.Labels[labelKey] = string(app.UID)
		idx := -1
		for i := range dep.Spec.Template.Spec.Containers {
			if dep.Spec.Template.Spec.Containers[i].Name == "web" {
				idx = i
				break
			}
		}
		if idx < 0 {
			dep.Spec.Template.Spec.Containers = append(dep.Spec.Template.Spec.Containers, corev1.Container{Name: "web"})
			idx = len(dep.Spec.Template.Spec.Containers) - 1
		}
		c := &dep.Spec.Template.Spec.Containers[idx]
		c.Image = app.Spec.Image
		pi := -1
		for i := range c.Ports {
			if c.Ports[i].Name == "http" {
				pi = i
				break
			}
		}
		if pi < 0 {
			c.Ports = append(c.Ports, corev1.ContainerPort{Name: "http"})
			pi = len(c.Ports) - 1
		}
		c.Ports[pi].ContainerPort, c.Ports[pi].Protocol = app.Spec.Port, corev1.ProtocolTCP
		if !reflect.DeepEqual(old.Spec, dep.Spec) {
			if err := r.Update(ctx, dep); err != nil {
				return err
			}
		}
		result = dep
		return nil
	})
	return result, err
}
func (r *Reconciler) ensureService(ctx context.Context, app *WebApp) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		svc := &corev1.Service{}
		key := types.NamespacedName{Namespace: app.Namespace, Name: app.Name}
		err := r.Reader.Get(ctx, key, svc)
		selector := map[string]string{labelKey: string(app.UID)}
		ports := []corev1.ServicePort{{Name: "http", Port: app.Spec.Port, TargetPort: intstr.FromString("http"), Protocol: corev1.ProtocolTCP}}
		if apierrors.IsNotFound(err) {
			svc = &corev1.Service{ObjectMeta: metav1.ObjectMeta{Name: app.Name, Namespace: app.Namespace}, Spec: corev1.ServiceSpec{Type: corev1.ServiceTypeClusterIP, Selector: selector, Ports: ports}}
			if err := controllerutil.SetControllerReference(app, svc, r.Scheme); err != nil {
				return err
			}
			return r.Create(ctx, svc)
		}
		if err != nil {
			return err
		}
		if err := owned(svc, app); err != nil {
			return err
		}
		if svc.Spec.Type != "" && svc.Spec.Type != corev1.ServiceTypeClusterIP {
			return fmt.Errorf("managed Service type changed; refusing automatic conversion")
		}
		old := svc.DeepCopy()
		svc.Spec.Selector, svc.Spec.Ports = selector, ports
		// Keep ClusterIP(s), IPFamilies, IPFamilyPolicy and unrelated defaulted fields.
		if reflect.DeepEqual(old.Spec, svc.Spec) {
			return nil
		}
		return r.Update(ctx, svc)
	})
}
func (r *Reconciler) writeStatus(ctx context.Context, observed *WebApp, readyCount int32, ready bool, reason, message string) error {
	return retry.RetryOnConflict(retry.DefaultRetry, func() error {
		current := &WebApp{}
		if err := r.Reader.Get(ctx, client.ObjectKeyFromObject(observed), current); err != nil {
			return err
		}
		if current.UID != observed.UID || current.Generation != observed.Generation || !current.DeletionTimestamp.IsZero() {
			return ErrSuperseded
		}
		old := current.DeepCopyObject().(*WebApp)
		current.Status.ReadyReplicas = readyCount
		current.Status.ObservedGeneration = observed.Generation
		status := metav1.ConditionFalse
		if ready {
			status = metav1.ConditionTrue
		}
		apimeta.SetStatusCondition(&current.Status.Conditions, metav1.Condition{Type: "Ready", Status: status, Reason: reason, Message: message, ObservedGeneration: observed.Generation})
		if reflect.DeepEqual(old.Status, current.Status) {
			return nil
		}
		return r.Status().Update(ctx, current)
	})
}
